{"tool":"write","path":"reports/export.py","content":""""Reports CSV exporter."""

import csv
import io


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header."""
    names = list(columns)
    seen = set()
    for name in names:
        if not isinstance(name, str):
            raise ValueError("column names must be strings")
        if name in seen:
            raise ValueError("column names must be unique")
        seen.add(name)

    buffer = io.StringIO(newline="")
    writer = csv.writer(
        buffer,
        delimiter=",",
        lineterminator="\r\n",
        quoting=csv.QUOTE_MINIMAL,
        doublequote=True,
    )
    writer.writerow(names)

    for row in rows:
        record = []
        for name in names:
            value = row.get(name, "")
            record.append("" if value is None else str(value))
        writer.writerow(record)

    return buffer.getvalue()
